// Helper function to load all parts
export function getAllMonsterPartPaths(): string[] {
  const paths: string[] = [];
  ALL_MONSTER_PART_FOLDERS.forEach(folder => {
    folder.parts.forEach(part => {
      paths.push(`monster-parts/${folder.path}/${part}.png`);
    });
  });
  return paths;
}

